// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3681472708, 2069607370, 3748979141, 3662897605, 418361797, 1223811525, 772480954, 3661109701, 3498140101, 3388834245, 1684883909, 2771642821, 3475786181, 4163882206, 36127173, 4240110021];
const blocks = ["NFD U+010000-U+010FFF", "NFD U+011000-U+011FFF", "NFD U+012000-U+012FFF", "NFD U+013000-U+013FFF", "NFD U+014000-U+014FFF", "NFD U+015000-U+015FFF", "NFD U+016000-U+016FFF", "NFD U+017000-U+017FFF", "NFD U+018000-U+018FFF", "NFD U+019000-U+019FFF", "NFD U+01A000-U+01AFFF", "NFD U+01B000-U+01BFFF", "NFD U+01C000-U+01CFFF", "NFD U+01D000-U+01DFFF", "NFD U+01E000-U+01EFFF", "NFD U+01F000-U+01FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 65536 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
